"use client";

import { css } from "@codemirror/lang-css";
import { javascript } from "@codemirror/lang-javascript";
import { json } from "@codemirror/lang-json";
import type { Extension } from "@codemirror/state";
import CodeMirror from "@uiw/react-codemirror";
import { Braces, Check, Copy } from "lucide-react";
import { useCallback, useMemo, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { sandboxCodeMirrorTheme } from "@/lib/sandbox/codemirror-theme";
import type { SandboxFile } from "@/lib/sandbox/types";
import { getLanguageBadge, sandboxPanelClassName } from "@/lib/sandbox/utils";
import { cn } from "@/lib/utils";

interface CodeEditorProps {
  files: SandboxFile[];
  activeFileId: string;
  onActiveFileChange: (id: string) => void;
  onChange: (id: string, content: string) => void;
  onFormat?: () => void;
  readOnly?: boolean;
  className?: string;
}

export function CodeEditor({
  files,
  activeFileId,
  onActiveFileChange,
  onChange,
  onFormat,
  readOnly = false,
  className,
}: CodeEditorProps) {
  const [copied, setCopied] = useState(false);
  const activeFile = files.find((file) => file.id === activeFileId) ?? files[0];

  const extensions = useMemo(() => {
    if (!activeFile) {
      return sandboxCodeMirrorTheme;
    }
    const languageExt: Extension =
      activeFile.language === "css"
        ? css()
        : activeFile.language === "json"
          ? json()
          : javascript({ jsx: true, typescript: true });
    return [...sandboxCodeMirrorTheme, languageExt];
  }, [activeFile]);

  const handleCopy = useCallback(async () => {
    if (!activeFile) {
      return;
    }
    await navigator.clipboard.writeText(activeFile.content);
    setCopied(true);
    window.setTimeout(() => setCopied(false), 1500);
  }, [activeFile]);

  if (!activeFile) {
    return null;
  }

  return (
    <div className={cn(sandboxPanelClassName(className), "h-full w-full")}>
      <div className="flex shrink-0 overflow-x-auto border-border/60 border-b bg-sandbox-gutter">
        <div className="flex" role="tablist" aria-label="Open files">
          {files.map((file) => {
            const isActive = file.id === activeFileId;
            return (
              <button
                key={file.id}
                type="button"
                role="tab"
                aria-selected={isActive}
                onClick={() => onActiveFileChange(file.id)}
                className={cn(
                  "inline-flex shrink-0 items-center gap-1 border-border/60 border-r px-2.5 py-1.5 text-[11px] leading-tight transition-colors",
                  isActive
                    ? "border-t-2 border-t-primary bg-sandbox-editor-bg text-foreground"
                    : "border-t-2 border-t-transparent text-muted-foreground hover:bg-foreground/[0.04] hover:text-foreground"
                )}
              >
                <span className="whitespace-nowrap font-mono">{file.name}</span>
                {file.isDirty ? (
                  <span className="size-1.5 rounded-full bg-primary">
                    <span className="sr-only">Unsaved changes</span>
                  </span>
                ) : null}
              </button>
            );
          })}
        </div>
      </div>

      <div className="flex shrink-0 items-center justify-between gap-3 border-border/60 border-b bg-sandbox-gutter px-2.5 py-1">
        <p
          className="min-w-0 truncate font-mono text-[10px] text-muted-foreground"
          title={activeFile.path}
          translate="no"
        >
          {activeFile.path}
        </p>
        <div className="flex shrink-0 items-center gap-1">
          <Badge variant="outline" className="font-mono text-[10px]">
            {getLanguageBadge(activeFile.language)}
          </Badge>
          {onFormat ? (
            <Button variant="ghost" size="xs" onClick={onFormat}>
              <Braces data-icon="inline-start" />
              Format
            </Button>
          ) : null}
          <Button
            variant="ghost"
            size="xs"
            onClick={handleCopy}
            aria-label={copied ? "Code copied" : "Copy code"}
          >
            {copied ? (
              <Check data-icon="inline-start" />
            ) : (
              <Copy data-icon="inline-start" />
            )}
            {copied ? "Copied" : "Copy"}
          </Button>
        </div>
      </div>

      <div
        className="sandbox-codemirror relative min-h-0 w-full flex-1"
        role="tabpanel"
        translate="no"
        spellCheck={false}
      >
        <CodeMirror
          value={activeFile.content}
          height="100%"
          width="100%"
          theme="none"
          extensions={extensions}
          editable={!readOnly}
          onChange={(value) => onChange(activeFile.id, value)}
          basicSetup={{
            lineNumbers: true,
            foldGutter: false,
            highlightActiveLine: true,
            highlightActiveLineGutter: true,
            bracketMatching: true,
            indentOnInput: true,
            closeBrackets: true,
          }}
        />
      </div>
    </div>
  );
}

import { HighlightStyle, syntaxHighlighting } from "@codemirror/language";
import { Prec } from "@codemirror/state";
import { EditorView } from "@codemirror/view";
import { tags as t } from "@lezer/highlight";
import { sandboxSyntaxColors as c } from "@/lib/sandbox/syntax-theme";

const editorTheme = EditorView.theme(
  {
    "&": {
      color: c.foreground,
      backgroundColor: "var(--sandbox-editor-bg)",
      height: "100%",
      width: "100%",
    },
    ".cm-editor": {
      height: "100%",
      width: "100%",
    },
    ".cm-scroller": {
      overflow: "auto",
      fontFamily:
        '"Geist Mono", "Geist Mono Fallback", ui-monospace, SFMono-Regular, monospace',
      fontSize: "12px",
      lineHeight: "1.5",
    },
    ".cm-content": {
      caretColor: "#fafafa",
    },
    ".cm-gutters": {
      backgroundColor: "var(--sandbox-editor-bg)",
      color: "#52525b",
      border: "none",
      borderRight: "1px solid rgba(255,255,255,0.08)",
      flexShrink: "0",
    },
    ".cm-gutter.cm-lineNumbers": {
      backgroundColor: "var(--sandbox-editor-bg)",
      flexShrink: "0",
    },
    ".cm-selectionBackground, &.cm-focused .cm-selectionBackground": {
      backgroundColor: "rgba(255,255,255,0.1) !important",
    },
    "&.cm-focused": {
      outline: "none",
    },
    ".cm-cursor, .cm-dropCursor": {
      borderLeftColor: "#fafafa",
      borderLeftWidth: "2px",
    },
    ".cm-foldPlaceholder": {
      backgroundColor: "rgba(255,255,255,0.06)",
      border: "none",
      color: "#71717a",
      borderRadius: "0",
    },
    ".cm-matchingBracket, .cm-nonmatchingBracket": {
      backgroundColor: "rgba(255,255,255,0.08)",
      outline: "1px solid rgba(255,255,255,0.12)",
    },
  },
  { dark: true }
);

/** Wins over CodeMirror baseTheme + basicSetup injected styles. */
const editorLayoutTheme = Prec.highest(
  EditorView.theme(
    {
      ".cm-scroller": {
        display: "flex !important",
        alignItems: "flex-start !important",
      },
      ".cm-content": {
        padding: "4px 0 !important",
        flexShrink: "0",
      },
      ".cm-line": {
        padding: "0 16px 0 10px !important",
      },
      ".cm-lineNumbers .cm-gutterElement": {
        padding: "0 10px 0 12px !important",
        minWidth: "1.75em !important",
        textAlign: "right",
        whiteSpace: "nowrap",
        backgroundColor: "var(--sandbox-editor-bg)",
      },
      ".cm-activeLineGutter": {
        backgroundColor: "oklch(0.17 0 0) !important",
        borderRadius: "0 !important",
      },
      ".cm-activeLine": {
        backgroundColor: "rgba(255,255,255,0.03)",
        borderRadius: "0 !important",
      },
    },
    { dark: true }
  )
);

const highlightStyle = HighlightStyle.define([
  { tag: t.keyword, color: c.keyword },
  { tag: [t.name, t.deleted, t.character, t.macroName], color: c.name },
  { tag: [t.propertyName], color: c.property },
  {
    tag: [t.function(t.variableName), t.labelName],
    color: c.function,
  },
  { tag: [t.color, t.constant(t.name), t.standard(t.name)], color: c.constant },
  { tag: [t.definition(t.name), t.separator], color: c.name },
  {
    tag: [
      t.typeName,
      t.className,
      t.number,
      t.changed,
      t.annotation,
      t.modifier,
      t.self,
      t.namespace,
    ],
    color: c.type,
  },
  {
    tag: [
      t.operator,
      t.operatorKeyword,
      t.url,
      t.escape,
      t.regexp,
      t.link,
      t.special(t.string),
    ],
    color: c.operator,
  },
  { tag: [t.meta, t.comment], color: c.comment, fontStyle: "italic" },
  { tag: t.strong, fontWeight: "bold", color: "#fafafa" },
  { tag: t.emphasis, fontStyle: "italic" },
  { tag: t.strikethrough, textDecoration: "line-through" },
  { tag: t.link, color: c.property, textDecoration: "underline" },
  { tag: t.heading, fontWeight: "bold", color: "#fafafa" },
  { tag: [t.atom, t.bool, t.special(t.variableName)], color: c.constant },
  { tag: [t.processingInstruction, t.string, t.inserted], color: c.string },
  { tag: t.invalid, color: c.invalid, borderBottom: "1px dotted #ef4444" },
]);

export const sandboxCodeMirrorTheme = [
  editorTheme,
  editorLayoutTheme,
  syntaxHighlighting(highlightStyle),
];

export type ViewportSize = "desktop" | "tablet" | "mobile";
export type ConsoleLevel = "log" | "info" | "warn" | "error";
export type PreviewStatus = "idle" | "loading" | "ready" | "error";

export interface SandboxFile {
  id: string;
  name: string;
  path: string;
  language: "tsx" | "ts" | "css" | "json";
  content: string;
  isDirty?: boolean;
}

export interface ConsoleMessage {
  id: string;
  level: ConsoleLevel;
  message: string;
  timestamp: Date;
  source?: string;
}

export interface PackageInstallEvent {
  id: string;
  name: string;
  version: string;
  status: "pending" | "success" | "error";
  output?: string;
}

export interface RuntimeError {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}

export interface FileTreeNode {
  id: string;
  name: string;
  type: "file" | "folder";
  children?: FileTreeNode[];
  fileId?: string;
}

export interface SandboxState {
  files: SandboxFile[];
  originalContents: Record<string, string>;
  activeFileId: string;
  fileTree: FileTreeNode[];
  consoleMessages: ConsoleMessage[];
  installEvents: PackageInstallEvent[];
  runtimeError: RuntimeError | null;
  previewStatus: PreviewStatus;
  viewport: ViewportSize;
  previewSrcDoc: string;
  consoleCollapsed: boolean;
}

import { cn } from "@/lib/utils";
import type { FileTreeNode, SandboxFile } from "./types";

export function sandboxPanelClassName(className?: string): string {
  return cn(
    "flex h-full min-h-0 min-w-0 flex-col overflow-hidden bg-transparent",
    className
  );
}

export function sandboxPanelHeaderClassName(className?: string): string {
  return cn(
    "flex shrink-0 items-center justify-between gap-2 border-b border-border/60 bg-sandbox-gutter px-2.5 py-1.5",
    className
  );
}

export function sandboxShellClassName(className?: string): string {
  return cn(
    "overflow-hidden rounded-xl border border-border bg-card ring-1 ring-foreground/10",
    className
  );
}

export function getLanguageLabel(language: SandboxFile["language"]): string {
  const labels: Record<SandboxFile["language"], string> = {
    tsx: "TypeScript React",
    ts: "TypeScript",
    css: "CSS",
    json: "JSON",
  };
  return labels[language];
}

export function getLanguageBadge(language: SandboxFile["language"]): string {
  const badges: Record<SandboxFile["language"], string> = {
    tsx: "TSX",
    ts: "TS",
    css: "CSS",
    json: "JSON",
  };
  return badges[language];
}

export function formatTimestamp(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function formatCode(content: string): string {
  const lines = content.split("\n");
  let indent = 0;
  const formatted: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      formatted.push("");
      continue;
    }

    if (/^[}\])]/.test(trimmed)) {
      indent = Math.max(0, indent - 1);
    }

    formatted.push(`${"  ".repeat(indent)}${trimmed}`);

    const openBrackets = (trimmed.match(/[{[(]/g) || []).length;
    const closeBrackets = (trimmed.match(/[}\])]/g) || []).length;
    indent += openBrackets - closeBrackets;
    indent = Math.max(0, indent);
  }

  return formatted.join("\n");
}

export function findFileIdInTree(
  nodes: FileTreeNode[],
  fileId: string
): string | null {
  for (const node of nodes) {
    if (node.type === "file" && node.fileId === fileId) {
      return node.id;
    }
    if (node.children) {
      const found = findFileIdInTree(node.children, fileId);
      if (found) {
        return found;
      }
    }
  }
  return null;
}

export function removeFileFromTree(
  nodes: FileTreeNode[],
  fileId: string
): FileTreeNode[] {
  return nodes
    .filter((node) => !(node.type === "file" && node.fileId === fileId))
    .map((node) =>
      node.children
        ? { ...node, children: removeFileFromTree(node.children, fileId) }
        : node
    );
}

export function addFileToTree(
  nodes: FileTreeNode[],
  file: SandboxFile
): FileTreeNode[] {
  const parts = file.path.split("/");
  if (parts.length === 1) {
    return [
      ...nodes,
      {
        id: `tree-${file.id}`,
        name: file.name,
        type: "file" as const,
        fileId: file.id,
      },
    ];
  }

  const [folderName, ...rest] = parts;
  const existingFolderIndex = nodes.findIndex(
    (node) => node.type === "folder" && node.name === folderName
  );

  if (existingFolderIndex >= 0) {
    const folder = nodes[existingFolderIndex];
    const updatedFolder: FileTreeNode = {
      ...folder,
      children: addFileToTree(folder.children ?? [], {
        ...file,
        path: rest.join("/"),
      }),
    };
    return nodes.map((node, index) =>
      index === existingFolderIndex ? updatedFolder : node
    );
  }

  return [
    ...nodes,
    {
      id: `folder-${folderName}`,
      name: folderName,
      type: "folder" as const,
      children: addFileToTree([], { ...file, path: rest.join("/") }),
    },
  ];
}

export function getViewportWidth(viewport: "desktop" | "tablet" | "mobile") {
  const widths = {
    desktop: "100%",
    tablet: "768px",
    mobile: "390px",
  } as const;
  return widths[viewport];
}

export function formatRuntimeErrorForCopy(error: {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}): string {
  return `${error.title}: ${error.message}
at ${error.file}:${error.line}${error.column ? `:${error.column}` : ""}

${error.stack}`;
}
